@layer reset, base, components, utilities;

@layer reset {
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    img, picture, video, canvas, svg { display: block; max-inline-size: 100%; }
    input, button, textarea, select { font: inherit; }
    p, h1, h2, h3, h4, h5, h6 { overflow-wrap: break-word; }
    :root { --space: 1rem; line-height: 1.6; }
}

@layer base {
    :root {
        --color-bg: #fff;
        --color-text: #333;
        --color-primary: #3498db;
        --font-sans: system-ui, -apple-system, sans-serif;
    }
    body {
        background: var(--color-bg);
        color: var(--color-text);
        font-family: var(--font-sans);
        font-size: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
    }
    h1 { font-size: clamp(2rem, 1.5rem + 2vw, 3rem); line-height: 1.2; }
    h2 { font-size: clamp(1.5rem, 1.2rem + 1.5vw, 2rem); line-height: 1.3; }
    a { color: var(--color-primary); }
    :focus-visible {
        outline: 2px solid var(--color-primary);
        outline-offset: 2px;
    }
}

.nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 2rem;
    background: var(--color-bg);
    border-block-end: 1px solid #eee;
}
.nav__logo { font-weight: bold; font-size: 1.25rem; }
.nav__hamburger { display: none; cursor: pointer; }
.nav__menu {
    display: flex;
    gap: 2rem;
    list-style: none;
}
.nav__link {
    text-decoration: none;
    color: var(--color-text);
    position: relative;
    padding-block-end: 0.25rem;
}
.nav__link::after {
    content: "";
    position: absolute;
    inset-block-end: 0;
    inset-inline: 0;
    block-size: 2px;
    background: var(--color-primary);
    transform: scaleX(0);
    transform-origin: inline-start;
    transition: transform 0.3s ease;
}
.nav__link:hover::after { transform: scaleX(1); }

@media (max-width: 768px) {
    .nav__hamburger { display: flex; flex-direction: column; gap: 5px; }
    .nav__hamburger span { inline-size: 25px; block-size: 3px; background: var(--color-text); }
    .nav__menu {
        position: absolute;
        inset-block-start: 100%;
        inset-inline: 0;
        flex-direction: column;
        gap: 0;
        background: var(--color-bg);
        padding: 1rem 2rem;
        transform: scaleY(0);
        transform-origin: block-start;
        transition: transform 0.3s ease;
    }
    .nav__toggle:checked ~ .nav__menu { transform: scaleY(1); }
}

.dashboard {
    display: grid;
    grid-template-areas:
        "header header"
        "sidebar main"
        "footer footer";
    grid-template-columns: 250px 1fr;
    grid-template-rows: auto 1fr auto;
    min-block-size: 100vh;
}
@media (max-width: 768px) {
    .dashboard { grid-template-columns: 1fr; grid-template-areas: "header" "main" "footer"; }
    .sidebar { display: none; }
}
.dashboard__header { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main { grid-area: main; padding: 2rem; }
.dashboard__footer { grid-area: footer; }

.cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
}
.card {
    background: var(--color-card);
    border-radius: 12px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    overflow: hidden;
}
.card__header {
    padding: 1rem;
    background: linear-gradient(135deg, var(--color-primary), color-mix(in srgb, var(--color-primary) 70%, purple));
    color: white;
}
.card__body { padding: 1rem; }

body {
    min-block-size: 100vh;
    display: grid;
    place-items: center;
    background: linear-gradient(135deg, #667eea, #764ba2);
}
.login {
    background: rgba(255, 255, 255, 0.2);
    -webkit-backdrop-filter: blur(20px);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 16px;
    padding: 2.5rem;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
    inline-size: min(400px, 90vw);
    color: white;
    animation: fadeUp 0.6s ease both;
}
.login__input {
    inline-size: 100%;
    padding: 0.75rem 1rem;
    margin-block-end: 1rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 8px;
    color: white;
    transition: border-color 0.3s, box-shadow 0.3s;
}
.login__input:focus-visible {
    outline: none;
    border-color: rgba(255, 255, 255, 0.6);
    box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.2);
}
@keyframes fadeUp {
    from { opacity: 0; transform: translateY(20px); }
    to   { opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce) {
    .login { animation: none; }
}

.tooltip {
    position: relative;
    display: inline-block;
}
.tooltip__content {
    position: absolute;
    bottom: 100%;
    left: 50%;
    transform: translateX(-50%) translateY(8px) scale(0.9);
    background: #333;
    color: white;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    font-size: 0.875rem;
    white-space: nowrap;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s, transform 0.2s;
    pointer-events: none;
    margin-block-end: 8px;
}
.tooltip__content::after {
    content: "";
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    border: 6px solid transparent;
    border-block-start-color: #333;
}
.tooltip:hover .tooltip__content {
    opacity: 1;
    visibility: visible;
    transform: translateX(-50%) translateY(0) scale(1);
}

.loader-spin {
    inline-size: 40px;
    block-size: 40px;
    border: 4px solid #eee;
    border-block-start-color: var(--color-primary);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.loader-dots { display: flex; gap: 0.5rem; }
.loader-dots span {
    inline-size: 12px;
    block-size: 12px;
    background: var(--color-primary);
    border-radius: 50%;
    animation: pulse 1.4s ease-in-out infinite both;
}
.loader-dots span:nth-child(2) { animation-delay: 0.2s; }
.loader-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes pulse {
    0%, 80%, 100% { transform: scale(0); opacity: 0.5; }
    40% { transform: scale(1); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
    .loader-spin, .loader-dots span { animation: none; }
}
